ALTER TABLE public.base_perm_cleanup_runs ADD COLUMN IF NOT EXISTS snapshot jsonb;
ALTER TABLE public.base_perm_cleanup_runs ADD COLUMN IF NOT EXISTS final_transition boolean NOT NULL DEFAULT false;
ALTER TABLE public.base_perm_cleanup_runs ADD COLUMN IF NOT EXISTS result jsonb;
ALTER TABLE public.user_roles ADD COLUMN IF NOT EXISTS source_kind text NOT NULL DEFAULT 'legacy';
ALTER TABLE public.user_permission_overrides ADD COLUMN IF NOT EXISTS source_kind text NOT NULL DEFAULT 'legacy';
CREATE OR REPLACE FUNCTION private.final_permission_fingerprint() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT md5(coalesce((SELECT string_agg(to_jsonb(r)::text,'|' ORDER BY r.user_id,r.role_id) FROM user_roles r),'')||coalesce((SELECT string_agg(to_jsonb(o)::text,'|' ORDER BY o.user_id) FROM user_permission_overrides o),'')||private.org_fingerprint()||coalesce((SELECT string_agg(to_jsonb(r)::text,'|' ORDER BY r.id) FROM app_roles r),'')||coalesce((SELECT string_agg(p.id::text||p.status::text||p.is_system_admin::text,'|' ORDER BY p.id) FROM profiles p),'')||coalesce((SELECT string_agg(to_jsonb(s)::text,'|' ORDER BY s.user_id,s.specialty_id) FROM mkt_staff_specialties s),'')); $$;
CREATE OR REPLACE FUNCTION private.final_permission_account(u uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ev jsonb; protected_ boolean; unknown_ boolean; roles_ text[]; reason_ text; has_override boolean; BEGIN
 ev:=private.cleanup_account_eval(u,private.base_config());
 protected_:=private.cleanup_is_biz_staff(u) OR EXISTS(SELECT 1 FROM profiles WHERE id=u AND is_system_admin) OR EXISTS(SELECT 1 FROM user_roles ur JOIN app_roles r ON r.id=ur.role_id WHERE ur.user_id=u AND (ur.role_id IN ('role-admin','role-super-admin','role-kinh-doanh','role-9h328b84','role-g8qc3q2s','role-u0fzsvsp') OR EXISTS(SELECT 1 FROM unnest(r.permissions)p WHERE p LIKE 'biz.%' OR p LIKE 'k3.%'))) OR u=auth.uid();
 SELECT coalesce(array_agg(ur.role_id ORDER BY ur.role_id),'{}') INTO roles_ FROM user_roles ur WHERE ur.user_id=u AND ur.source_kind='legacy' AND ur.role_id IN ('role-leader-marketing','role-seo','role-content-web','role-local-seo','role-social','role-video','role-designer','role-0k2hmw8r','role-wupj68a6','role-xim870m3');
 unknown_:=EXISTS(SELECT 1 FROM user_roles WHERE user_id=u AND source_kind='legacy' AND NOT(role_id=ANY(roles_)) AND role_id<>'role-nhan-su-moi');
 has_override:=EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=u AND source_kind='legacy' AND use_custom);
 IF protected_ THEN reason_:='Kinh doanh, quản trị hoặc tài khoản phục hồi — giữ nguyên'; ELSIF unknown_ THEN reason_:='Nguồn Role chưa phân loại an toàn — giữ ngoại lệ'; ELSIF has_override THEN reason_:='Quyền cá nhân cũ có thể chứa nghiệp vụ Kinh doanh hoặc nguồn chưa rõ — giữ ngoại lệ'; ELSIF cardinality(roles_)=0 THEN reason_:='Không còn nguồn quyền cũ thuộc diện chuyển đổi'; ELSE reason_:='Chuyển đổi được; chưa bổ nhiệm sẽ không có quyền nghiệp vụ theo chức vụ. Công việc và người duyệt được giữ nguyên.'; END IF;
 RETURN ev||jsonb_build_object('status',CASE WHEN protected_ THEN 'protected' WHEN unknown_ OR has_override THEN 'review' WHEN cardinality(roles_)>0 THEN 'ready' ELSE 'protected' END,'reasons',jsonb_build_array(reason_),'removable',CASE WHEN protected_ OR unknown_ OR has_override THEN '[]'::jsonb ELSE to_jsonb(roles_) END,'final_transition',true); END $$;
CREATE OR REPLACE FUNCTION public.base_perm_final_preview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE accounts_ jsonb; BEGIN
 IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được chuyển đổi quyền.'; END IF;
 SELECT coalesce(jsonb_agg(private.final_permission_account(p.id)||jsonb_build_object('name',p.full_name,'account_status',p.status,'unit',(SELECT ou.name FROM org_assignments a JOIN org_units ou ON ou.id=a.unit_id WHERE a.user_id=p.id AND a.status='active' AND a.starts_at<=now() AND (a.ends_at IS NULL OR a.ends_at>now()) ORDER BY a.starts_at DESC LIMIT 1),'title',(SELECT t.name FROM org_assignments a JOIN org_titles t ON t.id=a.title_id WHERE a.user_id=p.id AND a.status='active' AND a.starts_at<=now() AND (a.ends_at IS NULL OR a.ends_at>now()) ORDER BY a.starts_at DESC LIMIT 1)) ORDER BY p.full_name),'[]') INTO accounts_ FROM profiles p WHERE EXISTS(SELECT 1 FROM user_roles WHERE user_id=p.id) OR EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=p.id AND use_custom);
 RETURN jsonb_build_object('fingerprint',private.final_permission_fingerprint(),'server_now',now(),'accounts',accounts_,'totals',jsonb_build_object('accounts',jsonb_array_length(accounts_),'ready',(SELECT count(*) FROM jsonb_array_elements(accounts_)a WHERE a->>'status'='ready'),'protected',(SELECT count(*) FROM jsonb_array_elements(accounts_)a WHERE a->>'status'='protected'),'review',(SELECT count(*) FROM jsonb_array_elements(accounts_)a WHERE a->>'status'='review'),'removable_roles',(SELECT coalesce(sum(jsonb_array_length(a->'removable')),0) FROM jsonb_array_elements(accounts_)a))); END $$;
CREATE OR REPLACE FUNCTION public.base_perm_final_execute(_users uuid[],_fingerprint text,_confirmation text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid; ev jsonb; run_ uuid; removed_ jsonb:='[]'; skipped_ jsonb:='[]'; snap_ jsonb; result_ jsonb; BEGIN
 IF NOT private.is_super_admin(auth.uid()) OR _confirmation IS DISTINCT FROM 'CHUYỂN ĐỔI QUYỀN' THEN RAISE EXCEPTION 'Cần Super Admin xác nhận CHUYỂN ĐỔI QUYỀN.'; END IF;
 IF coalesce(cardinality(_users),0)=0 OR cardinality(_users)>100 THEN RAISE EXCEPTION 'Danh sách tài khoản không hợp lệ.'; END IF;
 LOCK TABLE user_roles,user_permission_overrides,org_assignments,org_units,org_titles,org_parent_history,base_title_role_links,mkt_staff_specialties,mkt_specialties,app_roles,profiles,biz_appointments,biz_department_members,biz_management_assignments,biz_member_affiliations,base_org_state IN SHARE ROW EXCLUSIVE MODE;
 IF _fingerprint IS DISTINCT FROM private.final_permission_fingerprint() THEN RAISE EXCEPTION 'Dữ liệu thay đổi; xem trước lại.'; END IF;
 snap_:=jsonb_build_object('user_roles',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') FROM user_roles r),'overrides',(SELECT coalesce(jsonb_agg(to_jsonb(o)),'[]') FROM user_permission_overrides o),'roles',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') FROM app_roles r),'config',private.base_config(),'org_assignments',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM org_assignments a),'org_units',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM org_units a),'org_titles',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM org_titles a),'title_links',(SELECT coalesce(jsonb_agg(to_jsonb(l)),'[]') FROM base_title_role_links l),'specialties',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') FROM mkt_specialties s),'staff_specialties',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') FROM mkt_staff_specialties s),'biz_appointments',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM biz_appointments a),'biz_members',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM biz_department_members a),'biz_management',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM biz_management_assignments a),'biz_affiliations',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM biz_member_affiliations a),'effective',(SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',p.id,'permissions',(SELECT coalesce(jsonb_agg(r.key ORDER BY r.key),'[]') FROM base_permission_catalog r WHERE private.has_permission(p.id,r.key)))),'[]') FROM profiles p));
 FOREACH u IN ARRAY _users LOOP ev:=private.final_permission_account(u); IF ev->>'status'<>'ready' THEN skipped_:=skipped_||jsonb_build_array(ev); CONTINUE; END IF;
 removed_:=removed_||coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',u,'role_id',ur.role_id,'role_name',r.name,'created_at',ur.created_at,'source_kind',ur.source_kind,'lost',ev->'lost','pending_work',ev->'pending_work')) FROM user_roles ur JOIN app_roles r ON r.id=ur.role_id WHERE ur.user_id=u AND ur.source_kind='legacy' AND ur.role_id IN (SELECT jsonb_array_elements_text(ev->'removable'))),'[]');
 DELETE FROM user_roles WHERE user_id=u AND source_kind='legacy' AND role_id IN(SELECT jsonb_array_elements_text(ev->'removable')); END LOOP;
 IF jsonb_array_length(removed_)=0 THEN RAISE EXCEPTION 'Không có nguồn cũ nào đủ điều kiện chuyển đổi.'; END IF;
 result_:=jsonb_build_object('accounts',(SELECT count(DISTINCT x->>'user_id') FROM jsonb_array_elements(removed_)x),'removed',removed_,'skipped',skipped_,'at',now(),'base_role_applied',false);
 INSERT INTO base_perm_cleanup_runs(actor,fingerprint,removed,snapshot,final_transition,result) VALUES(auth.uid(),_fingerprint,removed_,snap_,true,result_) RETURNING id INTO run_; RETURN result_||jsonb_build_object('run_id',run_); END $$;
CREATE OR REPLACE FUNCTION public.base_perm_final_restore(_run uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r base_perm_cleanup_runs; n int; conflicts_ jsonb; BEGIN
 IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được khôi phục.'; END IF; LOCK TABLE user_roles,user_permission_overrides IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO r FROM base_perm_cleanup_runs WHERE id=_run AND final_transition FOR UPDATE; IF NOT FOUND OR r.restored THEN RAISE EXCEPTION 'Không tìm thấy lần chuyển đổi hoặc đã khôi phục.'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(ur)),'[]') INTO conflicts_ FROM user_roles ur WHERE ur.user_id IN(SELECT (x->>'user_id')::uuid FROM jsonb_array_elements(r.removed)x);
 INSERT INTO user_roles(user_id,role_id,created_at,source_kind) SELECT (x->>'user_id')::uuid,x->>'role_id',(x->>'created_at')::timestamptz,x->>'source_kind' FROM jsonb_array_elements(r.removed)x ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT;
 UPDATE base_perm_cleanup_runs SET restored=true,restored_at=now(),restored_by=auth.uid() WHERE id=_run; RETURN jsonb_build_object('restored_rows',n,'conflicts',conflicts_); END $$;
REVOKE ALL ON FUNCTION private.final_permission_fingerprint(),private.final_permission_account(uuid) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.base_perm_final_preview(),public.base_perm_final_execute(uuid[],text,text),public.base_perm_final_restore(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.base_perm_final_preview(),public.base_perm_final_execute(uuid[],text,text),public.base_perm_final_restore(uuid) TO authenticated,service_role;